impl RaceSoundSets {
    /// The sets of the kind-table entry `n` (two a kind of car), as a handle.
    #[cfg(test)]
    pub fn kind_list_of(
        n: usize,
    ) -> Result<rc2k_core::audio::commands::SoundList, crate::errors::BadInput> {
        crate::sound::owner::sound().race.sets.kind_list(n)
    }

    /// The sets of the kind-table entry `n` (two a kind of car), as a handle.
    pub fn kind_list(
        &self,
        n: usize,
    ) -> Result<rc2k_core::audio::commands::SoundList, crate::errors::BadInput> {
        let handle = self
            .kinds
            .get(n)
            .filter(|_| n < Self::KIND_ENTRIES)
            .ok_or(crate::errors::BadInput("a race sound kind past the table"))?
            .get();
        match offset_in(handle, RACE_LIST_TAG, Self::LEN) {
            Some(offset) => Ok(rc2k_core::audio::commands::SoundList::Race {
                offset: offset as u32,
            }),
            None => Err(crate::errors::BadInput(
                "a sound table's entry off its piece",
            )),
        }
    }

    /// Entry `n` of the list that starts `offset` bytes into the sets. A list is read on
    /// until its -1, through the next fields of the sets in their order where it runs past
    /// its own (as the original's list did); a read past the sets is none.
    pub fn list_entry(offset: u32, n: usize) -> Result<Option<u32>, crate::errors::BadInput> {
        let sets = &crate::sound::owner::sound().race.sets;
        if offset as usize >= core::mem::size_of::<Self>() {
            return Err(crate::errors::BadInput("a sound list off the race's sets"));
        }
        let at = (offset as usize).checked_add(4 * n);
        Ok(at.and_then(|at| crate::cells::load_value::<u32>(sets, at).ok()))
    }

    /// 0x512360: `off_512360`, 36 kinds of car, two sets each.
    #[cfg(test)]
    const KINDS_AT: usize = Self::START + 0x850;
    const KIND_ENTRIES: usize = 72;
    pub const START: usize = 0x511B10;
    pub const LEN: usize = 0x9D4;
}

